@Path("/") @POST @NoCache public Response issueUserInfoPost(){
  HttpHeaders headers=request.getHttpHeaders();
  String accessToken=this.appAuthManager.extractAuthorizationHeaderTokenOrReturnNull(headers);
  if (accessToken == null) {
    MultivaluedMap<String,String> formParams=request.getDecodedFormParameters();
    checkAccessTokenDuplicated(formParams);
    accessToken=formParams.getFirst(OAuth2Constants.ACCESS_TOKEN);
  }
  try {
    return issueUserInfo(accessToken);
  } catch (NullPointerException | IllegalArgumentException e) {
    throw new CorsErrorResponseException(cors.allowAllOrigins(), OAuthErrorException.INVALID_REQUEST, "Invalid request parameters", Response.Status.BAD_REQUEST);
  }
}
